import 'package:flutter/material.dart';import '../controllers/orders_controller.dart';class OrdersPage extends StatefulWidget{final OrdersController controller;const OrdersPage({super.key,required this.controller});@override State<OrdersPage> createState()=>_OrdersPageState();}class _OrdersPageState extends State<OrdersPage>{@override void initState(){super.initState();widget.controller.addListener(_on);widget.controller.load();}void _on()=>setState((){});@override void dispose(){widget.controller.removeListener(_on);super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Commandes'),actions:[IconButton(onPressed:widget.controller.load,icon:const Icon(Icons.refresh))]),body:widget.controller.loading?const Center(child:CircularProgressIndicator()):widget.controller.error!=null?Center(child:Text(widget.controller.error!)):ListView.builder(itemCount:widget.controller.items.length,itemBuilder:(c,i){final o=widget.controller.items[i];return ListTile(title:Text('Commande #${o.id}'),subtitle:Text('${o.status} • ${o.items.length} article(s)'),trailing:Text('${o.total.toStringAsFixed(0)} F'));}));}
